import type { OfflineRequestEnvelope } from '../sw-messages.js';
import { createComponentLogger } from '../../utils/component-logger.js';

const log = createComponentLogger('proxy');

export interface OfflineApiProxyResponse {
    status: number;
    headers?: Record<string, string>;
    body?: unknown;
}

export interface ServiceWorkerLikeClient {
    visibilityState?: string;
    postMessage(message: unknown, transfer?: Transferable[]): void;
}

export type MatchClients = () => Promise<ServiceWorkerLikeClient[]>;

export interface NetworkFirstApiOptions {
    timeoutMs?: number;
}

function jsonResponse(status: number, payload: Record<string, unknown>): Response {
    return new Response(JSON.stringify(payload), {
        status,
        headers: { 'Content-Type': 'application/json' },
    });
}

/**
 * What `readRoutableRequestBody` found. `unroutable` is the story-264 guard: the
 * offline router only ever speaks JSON (`offline-api-router.toRouteContext`
 * JSON.parses the envelope body), so anything else must be refused HERE rather
 * than serialized into the envelope and blamed on the router.
 */
type RoutableRequestBody =
    | { kind: 'empty' }
    | { kind: 'json'; text: string }
    | { kind: 'unroutable'; reason: string };

/**
 * Read a request body only if the offline router could actually handle it.
 *
 * Story 264: a multipart image upload that reaches the fallback (genuinely
 * offline) used to be read as text and handed to the router, which JSON.parsed
 * `------WebKitFormBoundary…` and reported the resulting SyntaxError as a 503
 * service outage ("No number after minus sign in JSON at position 1"). Both an
 * explicitly non-JSON `Content-Type` and a body that simply won't parse are
 * refused; a JSON body (with or without a declared Content-Type) still routes,
 * so the offline write path is untouched.
 */
async function readRoutableRequestBody(request: Request): Promise<RoutableRequestBody> {
    if (request.method === 'GET' || request.method === 'HEAD') {
        return { kind: 'empty' };
    }

    const text = await request.clone().text();
    if (text.length === 0) {
        return { kind: 'empty' };
    }

    const contentType = request.headers.get('Content-Type');
    if (contentType && !contentType.includes('application/json')) {
        return { kind: 'unroutable', reason: `its ${contentType.split(';')[0]} body cannot be served offline` };
    }

    try {
        JSON.parse(text);
    } catch (error) {
        return {
            kind: 'unroutable',
            reason: `its body is not JSON (${error instanceof Error ? error.message : 'unparseable'})`,
        };
    }

    return { kind: 'json', text };
}

export async function proxyApiRequestToClient(
    request: Request,
    matchClients: MatchClients,
    timeoutMs = 5000,
): Promise<Response> {
    // Story 264: refuse before looking for a client — an unroutable body is
    // unroutable no matter which window would receive it.
    const body = await readRoutableRequestBody(request);
    if (body.kind === 'unroutable') {
        const path = new URL(request.url).pathname;
        return jsonResponse(503, {
            error: `${request.method} ${path} requires the network: ${body.reason}`,
        });
    }

    const allClients = await matchClients();
    const targetClient = allClients.find((client) => client.visibilityState === 'visible') ?? allClients[0];

    if (!targetClient) {
        return jsonResponse(503, { error: 'Offline request failed: no active client available' });
    }

    const channel = new MessageChannel();
    const payload: OfflineRequestEnvelope = {
        type: 'offline-request',
        request: {
            method: request.method,
            url: request.url,
            body: body.kind === 'json' ? body.text : null,
        },
    };

    const responsePromise = new Promise<OfflineApiProxyResponse>((resolve, reject) => {
        const timer = setTimeout(() => {
            channel.port1.close();
            reject(new Error('Offline API proxy timed out'));
        }, timeoutMs);

        channel.port1.onmessage = (event: MessageEvent<OfflineApiProxyResponse>) => {
            clearTimeout(timer);
            channel.port1.close();
            resolve(event.data);
        };
    });

    targetClient.postMessage(payload, [channel.port2]);

    try {
        const proxied = await responsePromise;
        if (!proxied) {
            return jsonResponse(503, { error: 'Offline request failed: empty client response' });
        }

        const headers = new Headers(proxied.headers ?? {});
        const contentType = headers.get('Content-Type') ?? headers.get('content-type');

        if (proxied.status === 204) {
            return new Response(null, { status: 204, headers });
        }

        const body = typeof proxied.body === 'string'
            ? proxied.body
            : contentType?.includes('application/json')
                ? JSON.stringify(proxied.body ?? {})
                : String(proxied.body ?? '');

        return new Response(body, { status: proxied.status ?? 500, headers });
    } catch (error) {
        return jsonResponse(503, {
            error: 'Offline request failed: unable to route to local handler',
            detail: error instanceof Error ? error.message : 'unknown',
        });
    }
}

export async function networkFirstApi(
    request: Request,
    fetchImpl: typeof fetch,
    proxyFallback: (request: Request) => Promise<Response>,
    options: NetworkFirstApiOptions = {},
): Promise<Response> {
    const isManualTimeout = request.headers.has('X-Manual-AbortSignal');
    const headers = new Headers(request.headers);
    headers.delete('X-Manual-AbortSignal');

    let signal = request.signal;
    let timer: ReturnType<typeof setTimeout> | undefined;
    let timedOut = false;

    if (!isManualTimeout) {
        const timeoutMs = options.timeoutMs ?? 15000;
        const abortController = new AbortController();
        timer = setTimeout(() => {
            timedOut = true;
            abortController.abort();
        }, timeoutMs);

        signal = abortController.signal;
    }

    // Clone the request so that if the fetch fails, the proxyFallback can still read the body
    const requestClone = request.clone();

    try {
        // NOTE: For the Chrome flag "Insecure origins treated as secure" to bypass Mixed Content
        // for service worker fetches, the flag must include the FULL origin WITH port, e.g.:
        //   http://192.168.178.170:3000,http://192.168.178.18:3000
        // A bare IP without a port (port 80 implied) is a different origin and won't match.
        const fetchOptions: RequestInit = {
            method: request.method,
            headers,
            mode: 'cors',
            credentials: request.credentials,
            signal,
            redirect: 'follow',
        };

        // For non-GET/HEAD requests, include the body
        if (request.method !== 'GET' && request.method !== 'HEAD') {
            fetchOptions.body = await requestClone.arrayBuffer();
        }

        log.debug('networkFirstApi: trying network for', {
            method: fetchOptions.method,
            url: request.url,
            mode: fetchOptions.mode,
            credentials: fetchOptions.credentials,
        });

        const response = await fetchImpl(request.url, fetchOptions);
        log.debug(`networkFirstApi: network SUCCESS ${response.status} for ${request.url}`);
        return response;
    } catch (err) {
        // Story 362 (pwa-offline-06): a write our timer cut off may well have reached the server.
        // Replayed locally it synced back as a duplicate, so say the outcome is unknown instead.
        // A read is safe to answer from the replica; a write that failed to send still queues.
        if (timedOut && request.method !== 'GET' && request.method !== 'HEAD') {
            log.warn(`networkFirstApi: ${request.method} ${request.url} timed out after it was sent; outcome unknown, not replayed`);
            return jsonResponse(504, {
                error: 'The server did not answer in time, so the outcome is unknown — it may have been saved. Check before trying again.',
            });
        }
        log.info(`networkFirstApi: network FAILED, falling back to offline proxy for ${request.url}`, err);
        return proxyFallback(request);
    } finally {
        if (timer) clearTimeout(timer);
    }
}
