/**
 * Which requests the service worker claims as "API" — extracted from
 * `service-worker.ts` so it can be tested (stories 295/296).
 *
 * It was module-private, untested, and wrong. The prefix was derived as
 * `new URL(API_URL).pathname`, but `API_URL` is origin-only in every
 * configuration this app ships (`http://192.168.178.170:3000`), so the
 * pathname is `/` and `url.pathname.startsWith('/')` matched **every path on
 * the API origin** — not just `/api/*` as the code's own comment claimed.
 *
 * That silently defeated story 267. `isApiReachable()` probes
 * `${API_URL}/health` *specifically because* that path is supposed to bypass
 * the SW and get its answer from the network; instead the probe was
 * intercepted, fell through to the offline router (which answers any path it
 * does not own), and came back as a synthetic HTTP response. `pingBackend`
 * treats any response as "reached the server", so **an unroutable API probed
 * as reachable** — and a fresh device with no route to the LAN took the loud
 * `empty-failed` bootstrap path, three retries and a `console.error` blaming
 * the server, instead of the quiet `empty-offline` one. Observed on two
 * consecutive new phones (2026-08-21 and 2026-08-24); on the second the server
 * logged no traffic at all for the twenty minutes around that boot, confirming
 * the API was genuinely unreachable while the probe said otherwise.
 *
 * The prefix is now built the way callers build their URLs: whatever path
 * `API_URL` carries, followed by `/api/`. For an origin-only `API_URL` that is
 * `/api/`; for `http://host/base` it is `/base/api/`. The old derivation was
 * wrong in both cases — it also would have claimed `/base/anything`.
 */

import { isImageServeUrl } from './service-worker-image-cache.js';

export interface ApiScope {
    /** The backend origin, optionally with a base path. Callers append `/api/...` to it. */
    apiUrl: string;
    /** Excluded outright: the Pi gateway is never served by the offline router. */
    piGatewayUrl: string;
}

const API_PATH_SEGMENT = '/api/';

/**
 * The pathname prefix that marks a request as an API request, for a given
 * `API_URL`. Exported for the tests that pin the origin-only case.
 */
export function apiPathPrefix(apiUrl: string): string {
    const basePath = new URL(apiUrl).pathname.replace(/\/+$/, '');
    return `${basePath}${API_PATH_SEGMENT}`;
}

/**
 * True when the service worker should route `url` through the network-first
 * API chain (and therefore, on network failure, through the offline router).
 *
 * False means the request is passed straight to the network and the answer is
 * the network's — which is exactly what the reachability probe needs, and why
 * `/health` must not match.
 */
export function isApiRequestUrl(url: string, scope: ApiScope): boolean {
    let parsed: URL;
    try {
        parsed = new URL(url);
    } catch {
        return false;
    }

    // Explicitly exclude Pi Gateway requests. `startsWith` on the normalized
    // full URL, not the origin, so it still holds if the gateway and the API
    // ever share one.
    if (parsed.href.startsWith(scope.piGatewayUrl)) {
        return false;
    }

    if (parsed.origin !== new URL(scope.apiUrl).origin) {
        return false;
    }

    return parsed.pathname.startsWith(apiPathPrefix(scope.apiUrl));
}

/**
 * Which chain the service worker's fetch handler sends a request down (story
 * 392 extracted it from the handler):
 * - `api-image`: a content-stable image GET — cache-first (story 124).
 * - `api`: network-first, falling back to the offline router.
 * - `cross-origin`: not intercepted; the network's answer stands.
 * - `navigate`: bounded network, then the precached shell (story 282).
 * - `static`: same-origin assets, network-first with the static cache.
 */
export type FetchRoute = 'api-image' | 'api' | 'cross-origin' | 'navigate' | 'static';

export function classifyFetch(
    request: { url: string; method: string; mode: RequestMode },
    scope: ApiScope,
    serviceWorkerOrigin: string,
): FetchRoute {
    if (isApiRequestUrl(request.url, scope)) {
        return request.method === 'GET' && isImageServeUrl(request.url) ? 'api-image' : 'api';
    }
    if (new URL(request.url).origin !== serviceWorkerOrigin) {
        return 'cross-origin';
    }
    return request.mode === 'navigate' ? 'navigate' : 'static';
}
